// Focused regression for the repeated protection edge found by full LC1.
#[test]#[ignore="Actual retained app, running lobby and native Save/Quit/Continue with C1 bootstrap"]
fn local_ws_retained_app_running_continue_c1_recovers(){std::thread::Builder::new().name("local-ws-continue-c1".into()).stack_size(16*1024*1024).spawn(||tauri::async_runtime::block_on(async{
 let own=repo().join("spikes/noita-entry/.build/continue-correction-20261103").join(format!("retained-continue-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&own).unwrap();eprintln!("LOCAL_WS_RECOVERY {}",own.display());let mut service=Service::start(&own);network_profile::enable_elapsed_clock(&mut service,&own);let router=PipeHarness::new();let mut a=Client::start(&service.private(),&own.join("host"),None,false,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&a).await;let mut n=Native::start(&a,None,false);wait(&mut service,&a,"Continue host Ready",30,|v|current_state_is(v,"Ready")&&n.root.join("associated").is_file()).await;let world=a.handle.view()["rejoin"]["current_world"].clone();service.command(json!({"op":"peer"}));let mut b=Client::start(&service.private(),&own.join("peer"),None,true,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&b).await;let mut peer=Native::start(&b,None,false);wait(&mut service,&b,"Continue peer Ready",30,|v|current_state_is(v,"Ready")&&peer.root.join("associated").is_file()).await;let peer_world=b.handle.view()["rejoin"]["current_world"].clone();two_peer_ghost_with_start(&mut service,&a,&n,&world,&b,&peer,&peer_world,"startReviewed").await;fixture_input_write(peer.root.join("unaffected-check"),b"monitor peer through retained-app Continue").unwrap();elapsed(&mut service,1).await;
 for _ in 0..2{let saved=n.root.clone();n.close();assert_peer_healthy(&b,&peer);n=Native::start(&a,Some(&saved),true);ready_owner(&mut service,&a,&n,&world,true).await;assert_eq!(native_activity(&n)["seed_calls"],0);assert!(n.root.join("c1-protected-bootstrap.json").exists(),"Restored native never completed C1 metadata while protected");fresh_bidirectional_ghosts(&mut service,&a,&n,&b,&peer,"retained app running Continue").await;elapsed(&mut service,2).await;assert_peer_healthy(&b,&peer);let log=std::fs::read_to_string(n.root.join("native-output.txt")).unwrap();assert!(!log.contains("protection_failed"),"Continue protection repeatedly failed");}
 std::fs::write(own.join("results.json"),serde_json::to_vec_pretty(&json!({"passed":true,"appRetained":true,"runningLobby":true,"cooperativeSaveQuitContinueCycles":2,"sameWorld":world,"c1ProtectedBootstrap":true,"freshBidirectionalGhosts":true,"healthyPeer":true,"seedNotReset":true,"engineFactsInjected":true,"actualNoita":false})).unwrap()).unwrap();n.close();peer.close();a.close().await;b.close().await;service.close();
})).unwrap().join().unwrap();}
#[test]#[ignore="Actual ordinary scheduler/native/Server seed-refusal regression"]
fn local_ws_seed_refusal_has_current_reason(){std::thread::Builder::new().name("local-ws-seed-refusal".into()).stack_size(16*1024*1024).spawn(||tauri::async_runtime::block_on(async{
 let own=repo().join("spikes/noita-entry/.build/local-ws-client-20261101").join(format!("seed-refusal-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&own).unwrap();eprintln!("LOCAL_WS_RECOVERY {}",own.display());let mut service=Service::start(&own);network_profile::enable_elapsed_clock(&mut service,&own);let router=PipeHarness::new();let mut a=Client::start(&service.private(),&own.join("host"),None,false,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&a).await;let mut n=Native::start(&a,None,false);wait(&mut service,&a,"seed regression Ready",30,|v|current_state_is(v,"Ready")&&n.root.join("associated").is_file()).await;let world=a.handle.view()["rejoin"]["current_world"].clone();let saved=n.root.clone();fixture_input_write(n.root.join("start"),b"actual Start").unwrap();service.command(json!({"op":"start"}));ready_owner(&mut service,&a,&n,&world,true).await;
 let mut loss=expect_loss(&mut service,&n,"current wrong seed").await;loss.before_fault(&n);fixture_input_write(n.root.join("wrong-seed"),b"injected current seed mismatch").unwrap();wait(&mut service,&a,"specific current seed refusal",20,|v|v["connection"]["reason"]=="Loaded seed differs from stable world"&&v["fixture_current"]["pending_release"]==false&&native_activity(&n)["native_owned_hold"]==true).await;loss.protected(&n);elapsed(&mut service,3).await;assert_eq!(a.handle.view()["connection"]["reason"],"Loaded seed differs from stable world");n.close();n=Native::start(&a,Some(&saved),true);ready_owner(&mut service,&a,&n,&world,true).await;std::fs::write(own.join("results.json"),serde_json::to_vec_pretty(&json!({"passed":true,"engineFactsInjected":true,"actualNoita":false,"wrongSeedHeld":true,"specificReasonPersists":true,"correctRestoredContextRecovers":true})).unwrap()).unwrap();n.close();a.close().await;service.close();
})).unwrap().join().unwrap();}
#[test]#[ignore="Actual ordinary scheduler/native/Server; same-process Continue then two HTTP/WSS recoveries"]
fn local_ws_same_process_http_recovery_has_one_hold(){std::thread::Builder::new().name("local-ws-policy-recovery".into()).stack_size(16*1024*1024).spawn(||tauri::async_runtime::block_on(async{
 let own=repo().join("spikes/noita-entry/.build/local-ws-client-20261101").join(format!("policy-recovery-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&own).unwrap();eprintln!("LOCAL_WS_RECOVERY {}",own.display());let mut service=Service::start(&own);network_profile::enable_elapsed_clock(&mut service,&own);let router=PipeHarness::new();
 let mut a=Client::start(&service.private(),&own.join("host"),None,false,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&a).await;let mut na=Native::start(&a,None,false);wait(&mut service,&a,"policy host Ready",30,|v|current_state_is(v,"Ready")&&na.root.join("associated").is_file()).await;let wa=a.handle.view()["rejoin"]["current_world"].clone();service.command(json!({"op":"peer"}));let mut b=Client::start(&service.private(),&own.join("peer"),None,true,true,router.routes.clone(),service.watches.clone(),service.stores.clone()).await;bundle(&mut service,&b).await;let mut nb=Native::start(&b,None,false);wait(&mut service,&b,"policy peer Ready",30,|v|current_state_is(v,"Ready")&&nb.root.join("associated").is_file()).await;let wb=b.handle.view()["rejoin"]["current_world"].clone();two_peer_ghost_with_start(&mut service,&a,&na,&wa,&b,&nb,&wb,"startReviewed").await;fixture_input_write(nb.root.join("unaffected-check"),b"healthy peer through retained policy recovery").unwrap();elapsed(&mut service,1).await;same_process_continue(&mut service,&a,&na,&wa,&b,&nb).await;
 for _ in 0..2{let mut loss=expect_loss(&mut service,&na,"same-process HTTP/WSS recovery").await;loss.before_fault(&na);for kind in ["http","wss"]{service.command(json!({"op":"transport","kind":kind,"enabled":true,"target":"consumer"}));}wait(&mut service,&a,"current world protected during full service outage",20,|v|v["connection"]["state"]=="Reconnecting"&&native_activity(&na)["native_owned_hold"]==true).await;loss.protected(&na);assert_peer_healthy(&b,&nb);for kind in ["http","wss"]{service.command(json!({"op":"transport","kind":kind,"enabled":false,"target":"consumer"}));}ready_owner(&mut service,&a,&na,&wa,true).await;loss.rearm(&mut service,&na).await;fresh_bidirectional_ghosts(&mut service,&a,&na,&b,&nb,"same-process outage retains one hold and current C1").await;elapsed(&mut service,3).await;assert_peer_healthy(&b,&nb);}
 assert_eq!(a.local_bridge().view()["listener"]["authenticated"],1);assert_eq!(a.local_bridge().view()["listener"]["closed"],0);std::fs::write(own.join("results.json"),serde_json::to_vec_pretty(&json!({"passed":true,"engineFactsInjected":true,"actualNoita":false,"twoFullOutagesAfterSameProcessContinue":true,"oneHoldPerOutage":true,"localSocketNeverInterrupted":true,"sameWorld":wa,"peerUnaffected":true})).unwrap()).unwrap();na.close();nb.close();a.close().await;b.close().await;service.close();
})).unwrap().join().unwrap();}
